  3279  otError Mle::HandleChildIdResponse(const Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
  3280  {
  3281      OT_UNUSED_VARIABLE(aMessageInfo);
  3282
  3283      ThreadNetif &       netif = GetNetif();
  3284      otError             error = OT_ERROR_NONE;
  3285      LeaderDataTlv       leaderData;
  3286      SourceAddressTlv    sourceAddress;
  3287      Address16Tlv        shortAddress;
  3288      RouteTlv            route;
  3289      ActiveTimestampTlv  activeTimestamp;
  3290      PendingTimestampTlv pendingTimestamp;
  3291      Tlv                 tlv;
  3292      uint16_t            networkDataOffset;
  3293      uint16_t            offset;
  3294
  3295      // Source Address
  3296      SuccessOrExit(error = Tlv::GetTlv(aMessage, Tlv::kSourceAddress, sizeof(sourceAddress), sourceAddress));
  3297      VerifyOrExit(sourceAddress.IsValid(), error = OT_ERROR_PARSE);
  3298
  3299      LogMleMessage("Receive Child ID Response", aMessageInfo.GetPeerAddr(), sourceAddress.GetRloc16());
  3300
  3301      VerifyOrExit(mAttachState == kAttachStateChildIdRequest);
  3302
  3303      // Leader Data
  3304      SuccessOrExit(error = Tlv::GetTlv(aMessage, Tlv::kLeaderData, sizeof(leaderData), leaderData));
  3305      VerifyOrExit(leaderData.IsValid(), error = OT_ERROR_PARSE);
  3306
  3307      // ShortAddress
  3308      SuccessOrExit(error = Tlv::GetTlv(aMessage, Tlv::kAddress16, sizeof(shortAddress), shortAddress));
  3309      VerifyOrExit(shortAddress.IsValid(), error = OT_ERROR_PARSE);
  3310
  3311      // Network Data
  3312      error = Tlv::GetOffset(aMessage, Tlv::kNetworkData, networkDataOffset);
  3313      SuccessOrExit(error);
  3314
  3315      // Active Timestamp
  3316      if (Tlv::GetTlv(aMessage, Tlv::kActiveTimestamp, sizeof(activeTimestamp), activeTimestamp) == OT_ERROR_NONE)
  3317      {
  3318          VerifyOrExit(activeTimestamp.IsValid(), error = OT_ERROR_PARSE);
  3319
  3320          // Active Dataset
  3321          if (Tlv::GetOffset(aMessage, Tlv::kActiveDataset, offset) == OT_ERROR_NONE)
  3322          {
  3323              aMessage.Read(offset, sizeof(tlv), &tlv);
  3324              netif.GetActiveDataset().Set(activeTimestamp, aMessage, offset + sizeof(tlv), tlv.GetLength());
  3325          }
  3326      }
  3327
  3328      // clear Pending Dataset if device succeed to reattach using stored Pending Dataset
  3329      if (mReattachState == kReattachPending)
  3330      {
  3331          netif.GetPendingDataset().Clear();
  3332      }
  3333
  3334      // Pending Timestamp
  3335      if (Tlv::GetTlv(aMessage, Tlv::kPendingTimestamp, sizeof(pendingTimestamp), pendingTimestamp) == OT_ERROR_NONE)
  3336      {
  3337          VerifyOrExit(pendingTimestamp.IsValid(), error = OT_ERROR_PARSE);
  3338
  3339          // Pending Dataset
  3340          if (Tlv::GetOffset(aMessage, Tlv::kPendingDataset, offset) == OT_ERROR_NONE)
  3341          {
  3342              aMessage.Read(offset, sizeof(tlv), &tlv);
  3343              netif.GetPendingDataset().Set(pendingTimestamp, aMessage, offset + sizeof(tlv), tlv.GetLength());
  3344          }
  3345      }
  3346      else
  3347      {
  3348          netif.GetPendingDataset().ClearNetwork();
  3349      }
  3350
  3351  #if OPENTHREAD_CONFIG_ENABLE_TIME_SYNC
  3352      // Sync to Thread network time
  3353      if (aMessage.GetTimeSyncSeq() != OT_TIME_SYNC_INVALID_SEQ)
  3354      {
  3355          GetNetif().GetTimeSync().HandleTimeSyncMessage(aMessage);
  3356      }
  3357  #endif
  3358
  3359      // Parent Attach Success
  3360
  3361      SetStateDetached();
  3362
  3363      SetLeaderData(leaderData.GetPartitionId(), leaderData.GetWeighting(), leaderData.GetLeaderRouterId());
  3364
  3365      if (!IsRxOnWhenIdle())
  3366      {
  3367          netif.GetMeshForwarder().GetDataPollManager().SetAttachMode(false);
  3368          netif.GetMeshForwarder().SetRxOnWhenIdle(false);
  3369      }
  3370      else
  3371      {
  3372          netif.GetMeshForwarder().SetRxOnWhenIdle(true);
  3373      }
  3374
  3375      // Route
  3376      if ((Tlv::GetTlv(aMessage, Tlv::kRoute, sizeof(route), route) == OT_ERROR_NONE) && IsFullThreadDevice())
  3377      {
  3378          SuccessOrExit(error = netif.GetMle().ProcessRouteTlv(route));
  3379      }
  3380
  3381      mParent = mParentCandidate;
  3382      ResetParentCandidate();
  3383
  3384      mParent.SetRloc16(sourceAddress.GetRloc16());
  3385
  3386      netif.GetNetworkDataLeader().SetNetworkData(leaderData.GetDataVersion(), leaderData.GetStableDataVersion(),
  3387                                                  !IsFullNetworkData(), aMessage, networkDataOffset);
  3388
  3389      netif.GetActiveDataset().ApplyConfiguration();
  3390
  3391      SetStateChild(shortAddress.GetRloc16());
  3392
  3393  exit:
  3394
  3395      if (error != OT_ERROR_NONE)
